import random,math
random.seed(1007); r=44376/275; best=(-1,None)
def mm(A,B): return [[sum(A[i][k]*B[k][j] for k in range(3)) for j in range(3)] for i in range(3)]
def sub(A,B): return [[A[i][j]-B[i][j] for j in range(3)] for i in range(3)]
def det(A): return A[0][0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1])-A[0][1]*(A[1][0]*A[2][2]-A[1][2]*A[2][0])+A[0][2]*(A[1][0]*A[2][1]-A[1][1]*A[2][0])
def hmat():
 d=[random.gauss(0,1) for _ in range(3)]; m=sum(d)/3; d=[x-m for x in d]; A=[[0j]*3 for _ in range(3)]
 for i in range(3): A[i][i]=d[i]
 for i,j in [(0,1),(0,2),(1,2)]:
  z=random.gauss(0,1)+1j*random.gauss(0,1); A[i][j]=z; A[j][i]=z.conjugate()
 n=math.sqrt(sum(abs(z)**2 for row in A for z in row)); return [[z/n for z in row] for row in A]
for _ in range(100000):
 X=hmat();Y=hmat();C=sub(mm(X,Y),mm(Y,X));K=sum(abs(z)**2 for row in C for z in row);P=abs(det(C))**2;S=K+r*P
 if S>best[0]: best=(S,(K,P,X,Y))
print(best[0],best[1][0],best[1][1])
